// Pull existing job_url and job_id values from the Google Sheets read node.
// This node ran upstream, so its data is available via $('Read Existing Job URLs').
let existingUrls = new Set();
let existingKeys = new Set();
try {
  const sheetItems = $('Read Existing Job URLs').all();
  for (const si of sheetItems) {
    const url = si.json.job_url || si.json['E'] || '';
    const jobId = si.json.job_id || si.json['K'] || '';
    const key = (si.json.company || '') + '__' + (si.json.job_title || '');
    if (url) existingUrls.add(url.trim());
    if (jobId) existingUrls.add(jobId.trim());
    if (key && key !== '__') existingKeys.add(key.trim().toLowerCase());
  }
} catch(e) {
  // Sheet may be empty on first run — that's fine.
}

const seen = new Set();
const results = [];

for (const item of $input.all()) {
  const j = item.json;
  // Drop placeholder empty items from normalize nodes
  if (j.skip || j.job_id === 'skip_empty') continue;

  const url = (j.job_url || '').trim();
  const id = (j.job_id || '').trim();
  const key = ((j.company || '') + '__' + (j.job_title || '')).trim().toLowerCase();

  if (url && existingUrls.has(url)) continue;
  if (id && existingUrls.has(id)) continue;
  if (key && key !== '__' && existingKeys.has(key)) continue;
  if (url && seen.has(url)) continue;

  if (url) seen.add(url);
  results.push({ json: j });
}

return results;

const REJECT = [
