  /\bcanada only\b/i, /\buk only\b/i, /\bunited kingdom only\b/i,
  /\beu only\b/i, /\beurope only\b/i, /\baustralia only\b/i,
  /\bnew zealand only\b/i, /\bindia only\b/i,
  /\bmust be based in\b/i, /\bmust live in\b/i, /\bmust reside in\b/i,
  /\bauthorized to work in\b/i, /\bwork authorization required\b/i,
  /\blocal work permit\b/i, /\bwork permit required\b/i,
  /\bno international\b/i, /\bdomestic only\b/i,
  /\bin-office\b/i, /\bonsite\b/i, /\bon-site\b/i,
  /\boffice required\b/i, /\bhybrid\b/i,
  /\bremote within (us|uk|eu|europe|canada|australia)\b/i,
  /\bno contractors\b/i, /\bw2 only\b/i, /\bemployee only, no contractors\b/i,
  /\bfull.time employee only\b/i,
  /\bfixed us hours\b/i, /\bfixed eu hours\b/i,
  /\bmust work (est|pst|cst|cet|gmt) hours\b/i
];

const results = [];

for (const item of $input.all()) {
  const j = item.json;
  const text = [
    j.description || '',
    j.location_text || '',
    j.job_title || '',
    j.tags || ''
  ].join(' ');

  let rejected = false;
  let rejectReason = '';

  for (const pattern of REJECT) {
    if (pattern.test(text)) {
      rejected = true;
      rejectReason = 'Hard filter: ' + pattern.toString();
      break;
    }
  }

  if (!rejected) {
    results.push({ json: { ...j, hard_filter_passed: true, reject_reason: '' } });
  }
}

return results;

const results = [];

for (const item of $input.all()) {
  const j = item.json;

  const systemPrompt = `You are filtering remote jobs for Jerry, who lives in Taiwan.

The most important rule: Jerry must be able to work this job while physically based in Taiwan.

Do not pass a job only because it says "remote."

REJECT if:
- Requires the worker to live in the US, Canada, UK, EU, Europe, or Australia
- Requires local work authorization outside Taiwan
- Is hybrid, onsite, or remote within one specific country only
- Fixed working hours force Jerry to work 11pm-7am Taiwan time

KEEP only if ONE of these is true:
- Says worldwide remote / global remote / work from anywhere / anywhere
- Says APAC remote or Asia Pacific
- Explicitly accepts international contractors
- Company hires through EOR, Deel, Remote.com, Oyster, or B2B contractor agreement
- No country restriction mentioned at all (contractor role)

Return ONLY valid JSON, no markdown, no extra text:
{"taiwan_eligible":"yes/no/unclear","reason":"short reason under 20 words","location_risk":"low/medium/high","timezone_risk":"low/medium/high","contractor_possible":"yes/no/unclear","decision":"keep/reject/manual_check"}`;

  const jobContext = [
    'Title: ' + (j.job_title || 'Unknown'),
    'Company: ' + (j.company || 'Unknown'),
    'Location text: ' + (j.location_text || 'Not specified'),
    'Tags: ' + (j.tags || ''),
    'Description: ' + (j.description || '').substring(0, 2500)
  ].join('\n');

  const requestBody = JSON.stringify({
    model: 'claude-opus-4-7',
    max_tokens: 300,
    system: systemPrompt,
    messages: [{ role: 'user', content: jobContext }]
  });

  results.push({ json: { ...j, _ai_request_body: requestBody } });
}

return results;

const results = [];

for (const item of $input.all()) {
  const response = item.json;

  // Pull the original job data back from the previous node
  let originalJob = {};
  try {
    originalJob = $('Prepare AI Request Body').item.json || {};
  } catch(e) {}

  // The AI response body is the current item's json
  // Claude API response shape: { content: [{type:'text', text:'...'}] }
  let aiResult = { taiwan_eligible: 'unclear', reason: 'Parse error', location_risk: 'medium', timezone_risk: 'medium', contractor_possible: 'unclear', decision: 'manual_check' };

  try {
    const contentBlocks = response.content || [];
    const textBlock = contentBlocks.find(b => b.type === 'text');
    if (textBlock && textBlock.text) {
      const jsonStr = textBlock.text.trim().replace(/^```json?\s*/i, '').replace(/\s*```$/,'');
      aiResult = JSON.parse(jsonStr);
    }
  } catch(e) {
    aiResult.reason = 'Could not parse AI response: ' + (e.message || '');
  }

  // Re-attach all original job fields (strip the internal request body field)
  const { _ai_request_body, ...jobData } = (response._original || originalJob);

  results.push({
    json: {
      ...item.json,
      taiwan_eligible: aiResult.taiwan_eligible || 'unclear',
      taiwan_reason: aiResult.reason || '',
      location_risk: aiResult.location_risk || 'medium',
      timezone_risk: aiResult.timezone_risk || 'medium',
      contractor_possible: aiResult.contractor_possible || 'unclear',
      ai_decision: aiResult.decision || 'manual_check'
    }
  });
}

return results;

const ASYNC_HIGH = [/\basync\b/i, /\basynchronous\b/i, /\bfully async\b/i];
const ASYNC_MED = [/\bflexible hours\b/i, /\bflexible schedule\b/i, /\bwork across time zones\b/i, /\bno set hours\b/i, /\bown schedule\b/i];
const ASYNC_LOW = [/\bdistributed team\b/i, /\bremote.?first\b/i, /\bremote first\b/i, /\blow meeting\b/i, /\bwork from anywhere\b/i];

const HARD_REJECT = [
  /\bstrict 9.?to.?5\b/i,
  /\bfixed (us|est|pst|cst|cet|gmt) hours\b/i,
  /\bdaily live (calls|standup|sync) required\b/i,
  /\bmust overlap full.?(us|eu|uk|us east|us west|central) (business )?day\b/i,
  /\bcore hours.{0,30}(9am.5pm|9-5).{0,20}(est|pst|cet|gmt)\b/i
];

const results = [];

for (const item of $input.all()) {
  const j = item.json;
  const text = (j.description || '').toLowerCase();

  let hardRejected = false;
  for (const p of HARD_REJECT) {
    if (p.test(text)) { hardRejected = true; break; }
  }
  if (hardRejected) continue;

  let asyncLevel = 'unknown';
  if (ASYNC_HIGH.some(p => p.test(text))) asyncLevel = 'high';
  else if (ASYNC_MED.some(p => p.test(text))) asyncLevel = 'medium';
  else if (ASYNC_LOW.some(p => p.test(text))) asyncLevel = 'low';

  results.push({ json: { ...j, async_level: asyncLevel } });
}

return results;

const results = [];

const PRIMARY_ROLES = [
  /data analyst/i, /data scientist/i, /junior data scientist/i,
  /business intelligence/i, /\bbi analyst\b/i,
  /marketing analyst/i, /performance marketing analyst/i,
  /growth analyst/i, /\bai marketing/i, /\bai automation/i,
  /\bai workflow/i, /martech analyst/i, /marketing technologist/i,
  /creative strategist/i, /marketing data/i, /analytics engineer/i
];

const ADJACENT_ROLES = [
  /analyst/i, /\bdata\b/i, /marketing/i, /automation/i,
  /reporting/i, /dashboard/i, /insight/i, /research/i, /bi /i
];

for (const item of $input.all()) {
  const j = item.json;
  const titleLower = (j.job_title || '').toLowerCase();
  const descLower = (j.description || '').toLowerCase();
  const combined = titleLower + ' ' + descLower;
  const salaryText = (j.salary || '').toLowerCase();

  let score = 0;

  // ── Taiwan eligibility (40 pts max) ──────────────────────────────────
  const eligible = j.taiwan_eligible || 'unclear';
  const locRisk = j.location_risk || 'medium';
  const tzRisk = j.timezone_risk || 'medium';

  if (eligible === 'yes' && locRisk === 'low') {
    score += 40;
  } else if (eligible === 'yes' && locRisk === 'medium') {
    score += 35;
  } else if (/apac/i.test(combined)) {
    score += 30;
  } else if (eligible === 'unclear' && locRisk !== 'high') {
    score += 20;
  } else if (eligible === 'unclear') {
    score += 10;
  }

  // ── Async fit (25 pts max) ────────────────────────────────────────────
  const asyncLevel = j.async_level || 'unknown';
  if (asyncLevel === 'high') score += 25;
  else if (asyncLevel === 'medium') score += 20;
  else if (asyncLevel === 'low') score += 15;
  else if (/remote.?first|distributed/i.test(combined)) score += 10;

  // ── Role fit (25 pts max) ─────────────────────────────────────────────
  let roleCategory = 'other';
  if (PRIMARY_ROLES.some(p => p.test(titleLower) || p.test(combined))) {
    score += 25;
    roleCategory = 'primary';
  } else if (ADJACENT_ROLES.some(p => p.test(titleLower))) {
    score += 15;
    roleCategory = 'adjacent';
  }

  // ── Salary fit (10-25 pts) ────────────────────────────────────────────
  const salaryNums = salaryText.match(/(\d[\d,\.]+)/g) || [];
  const salaryValues = salaryNums.map(s => parseFloat(s.replace(/,/g, ''))).filter(n => n > 100);
  const maxSalary = salaryValues.length > 0 ? Math.max(...salaryValues) : 0;

  if (maxSalary >= 5000) score += 25;
  else if (maxSalary >= 3000) score += 15;
  else if (maxSalary >= 1000) score += 10;
  else if (j.salary && j.salary.trim()) score += 10;

  // ── Why good fit summary ──────────────────────────────────────────────
  const reasons = [];
  if (eligible === 'yes') reasons.push('Taiwan-eligible confirmed by AI');
  else if (eligible === 'unclear') reasons.push('Taiwan eligibility unclear — manual check needed');
  if (asyncLevel === 'high') reasons.push('Fully async team');
  else if (asyncLevel === 'medium') reasons.push('Flexible hours');
  if (roleCategory === 'primary') reasons.push('Strong role match (data / AI marketing)');
  if (maxSalary >= 5000) reasons.push('Salary above $5k/mo');
  else if (maxSalary >= 3000) reasons.push('Salary above $3k/mo');
  if (j.contractor_possible === 'yes') reasons.push('Contractor-friendly');

  const decision =
    j.taiwan_eligible === 'no' || locRisk === 'high' || tzRisk === 'high' || score < 70
      ? 'reject'
      : score >= 85 && eligible === 'yes'
        ? 'apply'
        : 'manual_check';

  results.push({
    json: {
      ...j,
      score,
      role_category: roleCategory,
      why_good_fit: reasons.join('; ') || 'Moderate fit',
      decision,
      application_status: 'new',
      notes: ''
    }
  });
}

return results;

