// Collect all items from the score filter into one aggregated item for the digest.
// This node is connected AFTER Filter Score 70 Plus and receives all passing jobs.
const jobs = $input.all().map(i => i.json);

// Sort by score descending
jobs.sort((a, b) => (b.score || 0) - (a.score || 0));

return [{ json: { all_jobs: JSON.stringify(jobs), count: jobs.length } }];

const item = $input.first().json;
const jobs = JSON.parse(item.all_jobs || '[]');

const today = new Date().toLocaleDateString('en-US', {
  timeZone: 'Asia/Taipei',
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric'
});

const topJobs = jobs.filter(j => j.score >= 70).slice(0, 10);
const manualJobs = jobs.filter(j => j.taiwan_eligible === 'unclear' && j.score >= 75);

// Rejection summary (approximated from pre-filter metadata if tracked)
const rejected = {
  us_only: 0,
  eu_only: 0,
  hybrid: 0,
  timezone: 0
};

let subject = `[Taiwan Job Hunter] ${topJobs.length} async remote jobs found — ${today}`;

let body = `Daily Taiwan Eligible Async Remote Jobs\n`;
body += `${today}\n`;
body += `${'='.repeat(50)}\n\n`;
body += `Found ${topJobs.length} eligible jobs today.\n\n`;

if (topJobs.length === 0) {
  body += 'No jobs passed all filters today. Try again tomorrow.\n';
} else {
  body += `TOP JOBS\n${'─'.repeat(40)}\n\n`;
  topJobs.forEach((job, i) => {
    body += `${i + 1}. ${job.job_title}\n`;
    body += `   Company: ${job.company}\n`;
    body += `   Score: ${job.score}/100\n`;
    body += `   Taiwan Eligible: ${job.taiwan_eligible}\n`;
    body += `   Reason: ${job.taiwan_reason || 'N/A'}\n`;
    body += `   Async Level: ${job.async_level || 'Unknown'}\n`;
    body += `   Timezone Risk: ${job.timezone_risk || 'Unknown'}\n`;
    body += `   Location Risk: ${job.location_risk || 'Unknown'}\n`;
    body += `   Salary: ${job.salary || 'Not listed'}\n`;
    body += `   Contractor Possible: ${job.contractor_possible || 'Unknown'}\n`;
    body += `   Why It Fits Jerry: ${job.why_good_fit}\n`;
    body += `   Apply: ${job.job_url}\n`;
    body += `   Source: ${job.source}\n\n`;
  });
}

if (manualJobs.length > 0) {
  body += `\nMANUAL CHECK REQUIRED (${manualJobs.length} jobs — Taiwan eligibility unclear)\n${'─'.repeat(40)}\n\n`;
  manualJobs.slice(0, 5).forEach(job => {
    body += `• ${job.job_title} at ${job.company} (Score: ${job.score})\n`;
    body += `  Reason unclear: ${job.taiwan_reason || 'No AI reason given'}\n`;
    body += `  ${job.job_url}\n\n`;
  });
}

body += `\n${'='.repeat(50)}\n`;
body += `Powered by: Daily Taiwan Eligible Async Remote Job Hunter\n`;
body += `Filters passed: Taiwan hard filter → AI check → Async filter → Score >= 70\n`;

return [{ json: { subject, body, job_count: topJobs.length } }];
